const D = { energy: .55, scale: 1, density: .55, speed: 1, billow: .55, peaks: .5, hue: 210, x: .34, y: .44, style: 'inversion', act: 'settle', seed: 0, alpha: 1 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const ho = P.hue - 210;
const L3 = (a, b, f) => [a[0] + (b[0]-a[0])*f, a[1] + (b[1]-a[1])*f, a[2] + (b[2]-a[2])*f];
const sh = c => [hw(c[0] + ho), c[1], c[2]];
const NS = 5;                                    // undercast strata, 0 = farthest
const NR = 3;                                    // ridge planes, interleaved BETWEEN the strata

// ---------------- styles ----------------
const STY = {
  // the classic inversion: deep zenith, cold white undercast, blue-black peaks
  inversion:   { zen:[222,54,32], hor:[204,20,72], cFar:[206,10,76], cNear:[210,16,58], cLit:[200,5,96],
                 cShade:[216,26,40], peak:[218,34,22], sun:[42,18,98], topo:0, wv:0, grain:20 },
  // sunrise from above the deck — the cloud sea takes the fire, the peaks stay cold
  alpenglow:   { zen:[236,58,26], hor:[24,52,82], cFar:[26,30,74], cNear:[338,26,54], cLit:[36,44,98],
                 cShade:[286,34,32], peak:[248,36,18], sun:[38,60,99], topo:0, wv:0, grain:26 },
  // full moon over the deck — silver, dark key, still legible
  moonlit:     { zen:[236,62,12], hor:[214,30,40], cFar:[210,14,48], cNear:[214,20,34], cLit:[200,6,86],
                 cShade:[222,30,18], peak:[226,38,10], sun:[196,8,96], topo:0, wv:0, grain:14 },
  // ABSTRACTED: the cloud surface as a topographic sheet — stacked contours, no mass, no light
  topo:        { zen:[210,60,12], hor:[208,50,18], cFar:[186,44,60], cNear:[186,50,80], cLit:[184,30,96],
                 cShade:[200,44,24], peak:[188,40,94], sun:[186,26,96], topo:1, wv:0, grain:4 },
  // ABSTRACTED: a water-vapour satellite channel — form built from brightness temperature, not light
  watervapour: { zen:[30,8,10], hor:[34,14,26], cFar:[186,44,52], cNear:[8,72,72], cLit:[52,86,96],
                 cShade:[212,54,30], peak:[0,0,4], sun:[54,80,98], topo:0, wv:1, grain:8 }
};
const st = STY[P.style] || STY.inversion;

const en = Math.max(0, Math.min(1, P.energy));
const bi = Math.max(0, Math.min(1, P.billow));
const hy = height * P.y;                         // the horizon — where the deck runs out
const sunX = width * P.x;
const key = width + 'x' + height + '|' + P.style + '|' + P.seed + '|' + Math.round(P.hue) + '|' + P.scale.toFixed(2) + '|' + P.density.toFixed(2) + '|' + P.billow.toFixed(2) + '|' + P.peaks.toFixed(2) + '|' + P.y.toFixed(3) + '|' + P.x.toFixed(3);

const depthOf = j => (j + 1) / NS;                            // 0..1, 1 = nearest
const rowY = f => hy + Math.pow(f, 2.0) * (height - hy);      // perspective packing toward the horizon
const radOf = f => u * .026 * (.18 + f * 1.7) * P.scale * (.5 + bi);

if (!S.sky || S.key !== key) {
  const W = Math.max(2, Math.ceil(width)), H = Math.max(2, Math.ceil(height));
  const mk = (w, h) => { const g = createGraphics(Math.max(2, Math.ceil(w)), Math.max(2, Math.ceil(h))); g.colorMode(g.HSB, 360, 100, 100, 100); return g; };
  if (S.sky) { S.sky.remove(); S.str.forEach(x => x.g.remove()); S.rdg.forEach(x => x.remove()); }
  S.sky = mk(W, H);

  // --- sky above, and a cloud-sea base gradient below so no gap can ever show through ---
  const g = S.sky; g.noStroke();
  const zen = sh(st.zen), hor = sh(st.hor), cF = sh(st.cFar), cN = sh(st.cNear);
  for (let yy = 0; yy < H; yy++) {
    let c;
    if (yy < hy) c = L3(zen, hor, Math.pow(Math.min(1, yy / Math.max(1, hy)), .7));
    else c = L3(cF, cN, Math.pow(Math.min(1, (yy - hy) / Math.max(1, H - hy)), .6));
    g.fill(c[0], c[1], c[2]); g.rect(0, yy, W, 1);
  }

  // --- ridge planes: dark rock breaching the deck. Built first so strata can bury them. ---
  S.rdg = [];
  const peakC = sh(st.peak);
  for (let r = 0; r < NR; r++) {
    const f = (r + .6) / NR;                        // 0..1 near-ness, matched to the strata
    const ry = rowY(f);
    const bh = Math.max(4, Math.ceil(u * (.30 + f * .3)));
    const q = mk(W, bh);
    const haze = (1 - f) * .72;
    const c = L3(peakC, L3(cF, hor, .4), haze);
    const amp = u * (.05 + f * .17) * P.peaks * P.scale;
    q.noStroke(); q.fill(c[0], c[1], c[2], 96);
    q.beginShape(); q.vertex(-20, bh + 20);
    for (let xx = -20; xx <= W + 20; xx += 9) {
      // jagged: a broad envelope with sharp high-frequency teeth on top
      const n = Math.pow(Math.abs(Math.sin(xx * .0021 + fr(r * 5 + 1) * 6.3)), .7) * .8
              + Math.abs(Math.sin(xx * .0067 + fr(r * 5 + 2) * 6.3)) * .3
              + Math.abs(Math.sin(xx * .017 + fr(r * 5 + 3) * 6.3)) * .12;
      q.vertex(xx, bh * .74 - n * amp);
    }
    q.vertex(W + 20, bh + 20); q.endShape(q.CLOSE);
    // snow / lit faces catching the sun from the P.x side — texture, not a flat silhouette
    if (!st.topo) {
      const lit = L3(sh(st.cLit), L3(cF, hor, .4), haze * .8);
      q.noFill(); q.strokeWeight(Math.max(.5, u * .0014 * (.3 + f)));
      for (let i = 0; i < 46; i++) {
        const xx = fr(r * 31 + i * 3) * W;
        const n = Math.pow(Math.abs(Math.sin(xx * .0021 + fr(r * 5 + 1) * 6.3)), .7) * .8
                + Math.abs(Math.sin(xx * .0067 + fr(r * 5 + 2) * 6.3)) * .3
                + Math.abs(Math.sin(xx * .017 + fr(r * 5 + 3) * 6.3)) * .12;
        const py = bh * .74 - n * amp;
        q.stroke(lit[0], lit[1] * .7, lit[2], (18 + 30 * f) * (fr(i + r) * .7 + .3));
        q.line(xx, py, xx + (sunX > W / 2 ? -1 : 1) * u * .012, py + u * .02);
      }
      q.noStroke();
    }
    S.rdg.push(q); S.rdg[r].__y = ry - bh * .74;
  }

  // --- the undercast: NS tileable strata. Near ones are big and scroll fast, far ones
  //     small and slow. That rate spread IS the perspective. ---
  S.str = [];
  const cLit = sh(st.cLit), cShade = sh(st.cShade);
  for (let j = 0; j < NS; j++) {
    const f = depthOf(j);
    const rad = radOf(f);
    const by = rowY(f);
    const bh = Math.max(4, Math.ceil(rad * 5.2));
    const q = mk(W, bh);
    const haze = (1 - f) * .6;
    const n = Math.max(3, Math.floor((W / Math.max(6, rad * 1.15)) * (.5 + P.density)));
    q.noStroke();
    for (let i = 0; i < n; i++) {
      const bx = (i + .5) * (W / n) + (fr(j * 71 + i * 3) - .5) * (W / n) * .9;
      const yj = bh * .62 + (fr(j * 71 + i * 3 + 1) - .5) * rad * .8;
      const rr = rad * (.6 + fr(j * 71 + i * 3 + 2) * .9);
      for (let rep = -1; rep <= 1; rep++) {
        const px = bx + rep * W;
        if (st.topo) {
          // topo: the billow is a nest of contour rings — surface without substance
          q.noFill(); q.strokeWeight(Math.max(.5, u * .0011 * (.3 + f)));
          for (let c2 = 0; c2 < 4; c2++) {
            const cc = L3(sh(st.cNear), sh(st.cLit), c2 / 3);
            q.stroke(cc[0], cc[1], cc[2], 30 + c2 * 12);
            q.ellipse(px, yj + c2 * rr * .06, rr * (1 - c2 * .2), rr * (.62 - c2 * .12));
          }
          q.noStroke();
          continue;
        }
        // cauliflower: a shaded underside, a lit crown. Form from light.
        const lam = .5 + .5 * Math.cos((bx / W - P.x) * 3.0);
        for (let k = 0; k < 5; k++) {
          const kf = k / 4;
          const cc = L3(L3(cShade, cLit, Math.max(0, Math.min(1, kf * .7 + lam * .5))), L3(sh(st.cFar), sh(st.hor), .4), haze);
          q.fill(cc[0], cc[1] * (1 - kf * .25), Math.min(99, cc[2] + kf * 5 + (fr(j + i + k) - .5) * 7), st.wv ? 74 : 92);
          q.ellipse(px + (fr(j + i * 5 + k) - .5) * rr * .5, yj - kf * rr * .34, rr * (1.05 - kf * .18), rr * (.66 - kf * .1));
        }
        // the sunlit lip on the crown
        const lc = L3(cLit, L3(sh(st.cFar), sh(st.hor), .4), haze);
        q.fill(lc[0], lc[1] * .5, lc[2], (14 + 26 * lam) * (.4 + .6 * f));
        q.ellipse(px + (lam - .5) * rr * .5, yj - rr * .34, rr * .6, rr * .22);
      }
    }
    S.str.push({ g: q, f: f, y: by - bh * .62, rate: u * .0016 * Math.pow(f, 1.5) });
  }
  S.key = key;
}

// ---------------- act ----------------
const sec = ((Math.floor(K.section) % 8) + 8) % 8;
const ACT = { settle: { rise: 0, l: .9 + sec * .012 }, rise: { rise: -.02 - sec * .012, l: .85 + sec * .03 }, burnoff: { rise: .015 + sec * .012, l: 1 } };
const act = ACT[P.act] || ACT.settle;
// the whole deck breathes up and down over minutes — incommensurate, so it never re-phases
const lift = (act.rise * u * 2.4) + Math.sin(K.t * .0173) * u * .012 + Math.sin(K.t * .0411 + 1.4) * u * .006;

noStroke();
image(S.sky, 0, 0);

const scrX = (g, px, yy) => { const W2 = g.width; const ox = ((px % W2) + W2) % W2; image(g, ox - W2, yy); image(g, ox, yy); };

// interleave: ridge plane r sits BEHIND strata that are nearer than it. That occlusion is the depth.
let rIdx = 0;
for (let j = 0; j < NS; j++) {
  const s = S.str[j];
  while (rIdx < NR && (rIdx + .6) / NR <= s.f) {
    const q = S.rdg[rIdx];
    const dx = Math.sin(K.t * (.019 + rIdx * .008) + rIdx * 2.1) * u * .004 * (.3 + (rIdx + .6) / NR);
    image(q, dx, q.__y + lift * .35);
    rIdx++;
  }
  // near stratum ~37 px/s, far ~3 px/s at speed 1 — a majestic drift, and a wide enough
  // rate spread that the parallax reads as distance rather than as a sliding texture
  scrX(s.g, -K.t * s.rate * P.speed * 26 * (1 + s.f * .2), s.y + lift * (.4 + s.f * .8));
}
while (rIdx < NR) { const q = S.rdg[rIdx]; image(q, 0, q.__y + lift * .35); rIdx++; }

// ---------------- the sun / moon burning through above the deck ----------------
if (!st.topo) {
  const sunC = sh(st.sun);
  const sy = hy - u * (.06 + .10 * (1 - P.y)) + Math.sin(K.t * .0089) * u * .01;
  const gg = (.35 + .65 * en) * act.l * (.8 + .2 * K.swell) + A.lowmid * .22;
  blendMode(ADD);
  for (let i = 5; i >= 0; i--) {
    fill(sunC[0], sunC[1] * (.8 - i * .11), sunC[2], (3 + 6 * gg) * (1 - i * .12));
    ellipse(sunX + Math.sin(K.t * .0131) * width * .02, sy, u * (.045 + i * .26) * (1 + .04 * Math.sin(K.t * .37)), u * (.045 + i * .22));
  }
  blendMode(BLEND);
}

// ---------------- wisps tearing off the deck and spilling over the ridges ----------------
const cLit2 = sh(st.cLit);
const nw = Math.floor(8 + P.density * 18);
for (let i = 0; i < nw; i++) {
  // each wisp runs a continuous linear life and wraps — a real motion floor, never a pulse
  const life = ((K.t * (.035 + fr(i * 3 + 201) * .045) * P.speed + fr(i * 3 + 202)) % 1);
  const f = .35 + fr(i * 3 + 203) * .6;
  const wx = (life * width * 1.3 - width * .15 + fr(i * 3 + 204) * width) % (width * 1.2) - width * .1;
  const wy2 = rowY(f) - u * (.02 + fr(i * 3 + 205) * .09) + Math.sin(K.t * (.4 + i * .1) + i) * u * .008 + lift * .5;
  const fade = Math.sin(Math.PI * Math.min(1, life * 1.05));
  fill(cLit2[0], cLit2[1] * .6, cLit2[2], (3 + 9 * bi) * fade * (.4 + .6 * en));
  ellipse(wx, wy2, u * (.06 + .16 * f) * (.5 + fr(i) * .8), u * .012 * (.4 + f));
}

// ---------------- grain + frame ----------------
if (st.grain > 6) {
  const ng = Math.floor(st.grain * 6);
  for (let i = 0; i < ng; i++) {
    const px = ((fr(i * 3 + 601) * width) + Math.sin(K.t * .012 + i) * u * .003 + width) % width;
    const py = fr(i * 3 + 602) * height;
    fill(hw(st.zen[0] + ho), st.zen[1] * .5, fr(i * 3 + 603) > .5 ? 96 : 5, 3 + fr(i) * 6);
    rect(px, py, u * .0016, u * .0016);
  }
}
for (let i = 0; i < 5; i++) {
  noFill(); strokeWeight(u * .055);
  stroke(hw(st.zen[0] + ho), st.zen[1], 6, 18 * (1 - i * .17));
  rect(-u * .03 + i * u * .03, -u * .03 + i * u * .03, width + u * .06 - i * u * .06, height + u * .06 - i * u * .06);
}
noStroke();

if (P.alpha < 1) { fill(hw(st.zen[0] + ho), st.zen[1] * .5, 5, (1 - P.alpha) * 100); rect(0, 0, width, height); }
blendMode(BLEND);
drawingContext.shadowBlur = 0;
